-- ============================================================
-- 9. test_wide_table - 宽表（多字段，模拟真实报表场景）
-- ============================================================
BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE "TEST_WIDE_TABLE" CASCADE CONSTRAINTS';
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE != -942 THEN RAISE; END IF;
END;
/
CREATE TABLE "TEST_WIDE_TABLE" (
    "ID" NVARCHAR2(36) NOT NULL DEFAULT LOWER(REGEXP_REPLACE(RAWTOHEX(SYS_GUID()), '(.{8})(.{4})(.{4})(.{4})(.{12})', '\1-\2-\3-\4-\5')),
    "COMPANY" NVARCHAR2(100) NOT NULL,
    "DEPARTMENT" NVARCHAR2(50),
    "EMPLOYEE" NVARCHAR2(50) NOT NULL,
    "TITLE" NVARCHAR2(50),
    "SALARY" NUMBER(10,2),
    "BONUS" NUMBER(10,2) DEFAULT 0.00,
    "TAX_RATE" NUMBER(5,4) DEFAULT 0.0000,
    "HIRE_DATE" DATE,
    "CONTRACT_END" DATE,
    "WORK_YEARS" NUMBER(5) DEFAULT 0,
    "LEVEL" NUMBER(3) DEFAULT 1,
    "IS_MANAGER" NUMBER(1) DEFAULT 0,
    "KPI_SCORE" BINARY_FLOAT,
    "OFFICE_ADDR" NVARCHAR2(200),
    "MEMO" NCLOB,
    "CREATE_TIME" TIMESTAMP NOT NULL DEFAULT LOCALTIMESTAMP,
    "UPDATE_TIME" TIMESTAMP NOT NULL DEFAULT LOCALTIMESTAMP,
    "TIME_STAMP" TIMESTAMP NOT NULL DEFAULT LOCALTIMESTAMP,
    PRIMARY KEY ("ID"),
    CONSTRAINT "TEST_WIDE_TABLE_UK_COMPANY_EMPLOYEE" UNIQUE ("COMPANY", "EMPLOYEE")
);
CREATE INDEX "TEST_WIDE_TABLE_IDX_COMPANY_DEPT" ON "TEST_WIDE_TABLE" ("COMPANY", "DEPARTMENT");
CREATE INDEX "TEST_WIDE_TABLE_IDX_HIRE_DATE" ON "TEST_WIDE_TABLE" ("HIRE_DATE");

